import{_ as c,C as l,o as i,c as n,j as d,a as o,E as r,ak as a}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"形状与边界","description":"","frontmatter":{},"headers":[],"relativePath":"design/shape.md","filePath":"design/shape.md","lastUpdated":1790034296000}'),h={name:"design/shape.md"};function s(b,e,p,x,u,g){const t=l("XhTokenTable");return i(),n("div",null,[e[0]||(e[0]=d("h1",{id:"形状与边界",tabindex:"-1"},[o("形状与边界 "),d("a",{class:"header-anchor",href:"#形状与边界","aria-label":'Permalink to "形状与边界"'},"​")],-1)),e[1]||(e[1]=d("p",null,'圆角与边线是最容易长出第二套规则的地方——一个组件 6px、另一个 5px，看着都"差不多"。这里的规则是：圆角只有一条语义阶梯，边界只由描边承担，两者都由门禁逐条扫。',-1)),e[2]||(e[2]=d("h2",{id:"圆角阶梯",tabindex:"-1"},[o("圆角阶梯 "),d("a",{class:"header-anchor",href:"#圆角阶梯","aria-label":'Permalink to "圆角阶梯"'},"​")],-1)),r(t,{kind:"radius",names:["--xh-shape-inset","--xh-shape-control","--xh-shape-surface","--xh-shape-overlay","--xh-shape-circle","--xh-shape-pill"],notes:{"--xh-shape-inset":"4px · 嵌在控件里的内层：菜单项、勾选方框、字段内的清空钮、表格行选择框、色块","--xh-shape-control":"4px · 控件本体：Button、Input、Select trigger、Toggle、分页按钮、kbd、tooltip、Tabs / Steps trigger","--xh-shape-surface":"8px · 成面的静态容器：Card、Alert、Panel、列表容器、Segmented 与 Tabs 的轨道","--xh-shape-overlay":"12px · 脱离文档流的浮层：Popover、Menu、Dialog、Drawer、Toast","--xh-shape-circle":"50% · 宽高相等的圆：头像、单选圈、开关与滑杆的拇指、步骤圆点、加载环、悬浮单图标动作","--xh-shape-pill":"9999px · 只两类身份：状态 chip（Badge、Tag、结果标记）与一维对象（轨道、进度条、指示条、手柄、滚动条滑块）"}}),e[3]||(e[3]=a('<p>强制规则：</p><ul><li>普通 control 4px、surface 8px、overlay 12px；不存在 6px 或 10px。</li><li>pill 只给明确的胶囊身份；普通按钮、字段、卡片与浮层不用 pill。</li><li>正方盒（inline-size 与 block-size 同槽）必须取 circle，不得用 pill 冒充圆。</li><li>内层圆角不超过外层圆角减去内边距；相连控件（InputGroup、ButtonGroup）消除相接侧圆角。</li><li>亮色、暗色与紧凑密度不改变形状身份。</li><li>PromptInput 是登记过的例外：对话输入条允许 <code>--xh-shape-surface</code> 8px。</li></ul><h2 id="描边宽度" tabindex="-1">描边宽度 <a class="header-anchor" href="#描边宽度" aria-label="Permalink to &quot;描边宽度&quot;">​</a></h2>',3)),r(t,{names:["--xh-stroke-thin","--xh-stroke-thick","--xh-stroke-strong"],notes:{"--xh-stroke-thin":"一切描边与分隔线","--xh-stroke-thick":"焦点环、选中指示条、滑杆拇指描边","--xh-stroke-strong":"只给刻意登记的粗把手（图片裁切框、可调尺寸的拖柄）"}}),e[4]||(e[4]=a('<p>焦点环一律 <code>--xh-ring-width</code>（= thick，2px）+ <code>--xh-ring-offset</code>（画在盒内一圈，不改布局盒），环色 <code>--xh-ring-focus</code> 不随语气；实心面上的环取 <code>currentColor</code>。</p><h2 id="边界三选一" tabindex="-1">边界三选一 <a class="header-anchor" href="#边界三选一" aria-label="Permalink to &quot;边界三选一&quot;">​</a></h2><p>任何根面 / 主面只能取下表之一，阴影与淡底都不作为边界：</p><table tabindex="0"><thead><tr><th>形态</th><th>variant</th><th>描边</th><th>底</th><th>影</th></tr></thead><tbody><tr><td>描边</td><td><code>outline</code>（缺省）</td><td><code>--xh-stroke-thin solid --xh-border-default</code>；字段与控件盒用 <code>--xh-border-control</code>（缺省档与 default 同色）</td><td><code>--xh-bg-surface</code>；字段与控件盒 <code>transparent</code>，露出宿主的面</td><td>none（Card 加 <code>--xh-elevation-raised</code>）</td></tr><tr><td>淡底</td><td><code>subtle</code></td><td><code>--xh-stroke-thin solid transparent</code>（占位边，尺寸不跳）</td><td><code>--xh-bg-subtle</code>（有语气时 <code>--xh-tone-subtle</code>）</td><td>none</td></tr><tr><td>无壳</td><td><code>ghost</code></td><td>不写</td><td>不写</td><td>不写；只允许分隔线</td></tr></tbody></table><ul><li>有框 / 无框只走 <code>variant</code> 这一条轴：<code>outline | subtle | ghost</code>，可按下的表面多一档 <code>solid</code>。不存在 <code>bordered</code>、<code>borderless</code>、<code>plain | surface</code> 这类私有轴。</li><li><code>--xh-border-subtle</code> / <code>--xh-border-strong</code> 不得出现在根面 <code>border</code> 简写里，只能作 <code>border-block-start</code> 类分隔线与 <code>::after</code> 分隔伪元素。</li><li>raised 面（Card、Segmented 滑块、静止的滑杆拇指）必带 <code>--xh-border-default</code> 描边，影只是加成；只有可交互时允许 hover 抬升。</li></ul><h2 id="控件盒-浅边、不填底" tabindex="-1">控件盒：浅边、不填底 <a class="header-anchor" href="#控件盒-浅边、不填底" aria-label="Permalink to &quot;控件盒：浅边、不填底&quot;">​</a></h2><p>所有带边框的控件盒同一条规则：输入框壳、Checkbox / CheckboxGroup / Transfer / Tree / Table 的方框、RadioGroup / QuestionFlow 的圆圈、Switch 轨道描边、InputGroup 组壳、ColorPicker 控件、FileUpload 拖放区、SignaturePad 画布——</p><ul><li>静息不填底，露出宿主的面：白页上它就是白的，灰卡片上它就是灰的，不再自带一块白。</li><li>描边取 <code>--xh-border-control</code>，缺省档与浮层面板、卡片的 <code>--xh-border-default</code> 同色，页面里只有一种边线重量；<code>prefers-contrast: more</code> 才换到 3:1 的档。</li><li>hover 升 <code>--xh-border-control-hover</code> 并在透明上罩 45% 淡底；focus-within 换 <code>--xh-border-control-focus</code> + 焦点环；invalid 换 <code>--xh-border-invalid</code> + <code>--xh-ring-invalid</code>。</li><li>readOnly 只填 <code>--xh-bg-subtle</code> 不动描边；disabled = <code>--xh-border-default</code> + <code>--xh-bg-subtle</code> + <code>--xh-fg-disabled</code>，不靠 opacity。</li><li>字段的 <code>subtle</code> / <code>ghost</code> 只限有壳容器内（InputGroup、Command 面板、Toolbar）使用，hover / focus 必须浮出 <code>--xh-border-control</code>。</li><li>登记过的例外：浮层面板内嵌搜索（Command、Cascader）允许 <code>border-block-end</code> 下划线式；SignaturePad 不投影字段配方而自绘外壳，值必须与字段规则一致。</li></ul><p>需要白底的宿主写对应组件的底色槽，如 <code>--xh-text-field-control-bg: var(--xh-bg-canvas)</code>。</p><h2 id="选中与当前态的标记" tabindex="-1">选中与当前态的标记 <a class="header-anchor" href="#选中与当前态的标记" aria-label="Permalink to &quot;选中与当前态的标记&quot;">​</a></h2><p>按语义分类，每类只允许一种标记（门禁 <code>check-selection-marker</code> 逐成员核）：</p><table tabindex="0"><thead><tr><th>语义</th><th>对象</th><th>唯一标记</th></tr></thead><tbody><tr><td>浮层瞬态集合的选中</td><td>Select、Combobox、TreeSelect、Cascader、时间列、Mention</td><td>透明底 + 行尾对号（<code>--xh-fg-brand</code>），正文颜色与字重保持 rest</td></tr><tr><td>页内持久集合的选中</td><td>Tree、Listbox、Table row、Transfer、TagGroup、SideNav 当前项</td><td><code>--xh-bg-brand-subtle</code> 行面 + <code>--xh-fg-on-brand-subtle</code>；带勾选部件的集合再加前导对号。SideNav 当前项只有行面与字色，不画指示条</td></tr><tr><td>导航当前页</td><td>Tabs line、Anchor、NavigationMenu、Breadcrumb</td><td>透明面 + 2px 指示条 + <code>--xh-fg-brand-strong</code> + medium；Breadcrumb 当前页不可点、无指示条</td></tr><tr><td>格状当前</td><td>Pagination item、Steps indicator、Calendar 选中格</td><td>实心 <code>--xh-bg-brand</code> + <code>--xh-fg-on-brand</code>，不加粗</td></tr><tr><td>开关型（有滑块）</td><td>Segmented、Tabs segment</td><td>轨道 <code>--xh-bg-subtle</code> 内的白色抬起 indicator</td></tr><tr><td>开关型（无滑块）</td><td>Toggle、ToggleGroup item、Toolbar <code>aria-pressed</code></td><td><code>--xh-bg-brand-subtle</code> + <code>--xh-fg-on-brand-subtle</code></td></tr><tr><td>展开路径 / 打开中（不是选中）</td><td>Menu / Menubar / NavigationMenu trigger、Cascader in-path、Date / Time trigger</td><td>与所在家族 hover 同档的中性面，不用品牌色</td></tr></tbody></table><p><code>--xh-bg-brand-subtle</code> 专属&quot;选中 / 当前&quot;：Calendar 的今天改成 inset 1px <code>--xh-fg-brand</code> 环 + 品牌字，Steps 已完成改成中性面 + 品牌对号。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/colors">色彩</a> · <a href="/design/shadow">阴影与材质</a></li><li>指南：<a href="/guide/theme#形状阶梯">设计令牌与主题 · 形状阶梯</a></li></ul>',15))])}const T=c(h,[["render",s]]);export{m as __pageData,T as default};
